<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#eae5ce">
<title>The Tiny Trend Detective</title>
<style>
:root{--paper:#f9f5e6;--ink:#233e35;--mint:#a9c9b2;--red:#b43e2d;--muted:#57665a;--line:#c8c7ad}
*{box-sizing:border-box}body{margin:0;background:#eae5ce;color:var(--ink);font-family:"Palatino Linotype","Book Antiqua",Palatino,serif;font-size:18px;background-image:radial-gradient(#a49c7633 .65px,transparent .65px);background-size:6px 6px}button,input,select{font:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--red);outline-offset:4px}a{color:inherit;text-underline-offset:4px}button{border:1.5px solid var(--ink);background:var(--paper);color:var(--ink);border-radius:5px;padding:12px 18px;min-height:46px;box-shadow:0 3px 0 #233e3530;transition:transform .15s,background .15s}button:hover{background:#e2e9d6;transform:translateY(-1px)}button:active{transform:translateY(2px);box-shadow:none}button.primary{background:var(--ink);color:var(--paper)}button:disabled{cursor:default;opacity:.6;transform:none}button[aria-pressed=true]{background:var(--ink);color:var(--paper)}
.wrap{max-width:1160px;margin:auto;padding:26px 28px 70px}.top{display:flex;justify-content:space-between;gap:15px;border-bottom:2px solid var(--ink);padding-bottom:17px;font-family:"Courier New",monospace;font-size:12px;letter-spacing:1px;text-transform:uppercase}
header{display:grid;grid-template-columns:1.1fr 1fr;gap:40px;align-items:center;padding:45px 0 32px}.eyebrow,.tag{font-family:"Courier New",monospace;letter-spacing:2px;font-size:12px;text-transform:uppercase}.eyebrow{color:var(--red);font-weight:bold}h1{font-size:clamp(48px,6.8vw,85px);line-height:.93;letter-spacing:-3px;margin:18px 0 23px;font-weight:normal}h1 em{color:var(--red)}.intro{max-width:430px;line-height:1.55;color:var(--muted)}.illustration{margin:0;transform:rotate(2deg);border:9px solid var(--paper);box-shadow:7px 9px 0 #233e3522;background:var(--mint)}.illustration img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:cover}.illustration figcaption{font-family:"Courier New",monospace;font-size:11px;padding:9px;background:var(--paper)}.fallback{padding:35px;text-align:center;font-size:60px}
.tabs{display:flex;gap:10px;margin:8px 0 24px;flex-wrap:wrap}.tabs button{border-radius:40px;font-size:16px}.desk{background:var(--paper);border:1.5px solid var(--ink);box-shadow:8px 8px 0 #233e3520;padding:30px;border-radius:4px}.case-head{display:flex;justify-content:space-between;gap:18px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:18px}.case-head p{margin:0}.stamp{border:2px solid var(--red);color:var(--red);padding:7px 12px;transform:rotate(-5deg);font-size:12px;font-family:"Courier New",monospace;white-space:nowrap}h2{font-size:32px;font-weight:normal;margin:22px 0 12px;letter-spacing:-.7px}.question{line-height:1.5;max-width:700px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:25px 0}.chart-card{position:relative;display:block;text-align:left;padding:18px 15px;background:#fffdf5;min-width:0}.chart-card.selected{border:3px solid var(--red);padding:16.5px 13.5px}.card-label{display:flex;gap:10px;align-items:center;font-size:17px;min-height:42px}.letter{width:29px;height:29px;display:inline-grid;place-items:center;border-radius:50%;background:#e9e7d7;font-family:"Courier New",monospace;font-size:13px;flex-shrink:0}.chart-card svg{width:100%;height:100px;display:block;overflow:visible;margin:15px 0}.chart-caption{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);font-family:"Courier New",monospace}.feedback{line-height:1.6;padding:17px 20px;background:#e9eddd;border-left:4px solid var(--ink);margin:20px 0}.feedback p{margin:7px 0}.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.progress{color:var(--muted);font-size:14px}.footer-note{font-size:14px;line-height:1.6;color:var(--muted);margin:22px 0 0}.legend{font-size:13px;font-family:"Courier New",monospace;color:var(--muted)}[hidden]{display:none!important}.maker-layout{display:grid;grid-template-columns:1.3fr 1fr;gap:30px}.plot{width:100%;height:210px;display:block;border:1px solid var(--line);background:#fffdf5;border-radius:6px}.sliders{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;align-items:end;margin:20px 0}.sliders label{text-align:center;font-family:"Courier New",monospace;font-size:12px}.sliders input{width:100%;accent-color:var(--red);margin:15px 0}.sliders output{display:block;font-size:16px;color:var(--red)}.maker-controls{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.maker-controls button{font-size:14px;padding:10px}.note{background:#ebe9d4;padding:22px;border-radius:3px}.note h3{font-size:24px;font-weight:normal;margin:0 0 15px}.note p{line-height:1.6;font-size:16px}.readout{border-top:1px solid var(--line);padding-top:17px;line-height:1.9;font-family:"Courier New",monospace;font-size:13px}input[type=text]{width:100%;padding:12px;border:1px solid var(--ink);border-radius:3px;background:#fffdf5;margin:8px 0 17px}.toggles{display:flex;align-items:center;gap:10px;font-size:15px;margin:16px 0}.toggles input{width:20px;height:20px;accent-color:var(--ink)}footer{padding-top:35px;font-size:14px;line-height:1.8;display:flex;justify-content:space-between;gap:30px}.end{padding:20px 0}.end h2{font-size:46px}.medal{font-size:50px;color:var(--red)}@media(max-width:720px){.wrap{padding:20px 18px 40px}header{grid-template-columns:1fr;gap:20px;padding:30px 0}h1{font-size:clamp(48px,16vw,66px)}.intro{max-width:none}.illustration{max-width:450px;width:100%;justify-self:center;transform:rotate(1deg)}.cards{grid-template-columns:1fr;gap:14px}.chart-card{display:grid;grid-template-columns:1fr 1.2fr;align-items:center;column-gap:15px}.chart-card svg{margin:0;height:78px}.chart-caption{grid-column:2}.desk{padding:20px}.maker-layout{grid-template-columns:1fr;gap:20px}.sliders{gap:5px}.case-head{align-items:flex-start}.stamp{font-size:10px}footer{display:block}h2{font-size:28px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
</style></head>
<body><main class="wrap"><nav class="top" aria-label="Gallery"><a href="./">Chloe reads Jon</a><span>Field notes / No. 025</span></nav>
<header><div><div class="eyebrow">Small charts. Big clues.</div><h1>The Tiny<br><em>Trend</em><br>Detective.</h1><p class="intro">A number tells you where you are. A little line tells you how you got there. Put your eye for patterns to work in six tiny mysteries.</p></div>
<figure class="illustration"><img width="1200" height="800" alt="An illustrated mint-green detective desk: a magnifying glass studies rising, falling, steady and spiky chart cards beside a little mechanical robin." src="data:image/webp;base64,"><figcaption>THE FIELD DESK · Look for the story, not just the last dot.</figcaption></figure></header>
<div class="tabs" role="group" aria-label="Choose activity"><button id="detectTab" aria-pressed="true">01 / Solve the cases</button><button id="makeTab" aria-pressed="false">02 / Make a tiny trend</button></div>
<section class="desk" id="detect" aria-label="Trend mysteries">
<div class="case-head"><p class="tag" id="caseNo">Case 01 / 06</p><span class="stamp" id="stamp">OPEN CASE</span></div>
<div id="caseBody"><h2 id="title"></h2><p class="question" id="question"></p><p class="legend" id="legend"></p><div class="cards" id="cards"></div><div id="feedback" class="feedback" role="status" hidden></div><div class="actions"><button id="next" class="primary" hidden>Next case →</button><button id="hint">A small hint?</button><span class="progress" id="progress">No clock. No pressure. Just clues.</span></div></div>
<div class="end" id="end" hidden><div class="medal" aria-hidden="true">✳</div><h2>A fine eye for the little line.</h2><p class="question">Six cases closed. You spotted direction, surprises, rhythms, and the sneakiest clue of all: the scale.</p><p id="summary"></p><div class="actions"><button class="primary" id="openMaker">Make your own sparkline →</button><button id="restart">Reopen the cases</button></div></div>
<p class="footer-note">A sparkline is a compact chart woven into a sentence, table, or dashboard. These are invented examples, not live data. A line shows what happened, not why it happened or what must happen next.</p>
</section>
<section class="desk" id="make" hidden aria-label="Sparkline maker"><div class="case-head"><p class="tag">The pocket chart workshop</p><span class="stamp">MAKE A MARK</span></div><h2>Six moments. One little story.</h2><div class="maker-layout"><div><label for="chartName" class="tag">Name your chart</label><input id="chartName" type="text" maxlength="60" value="Robot club attendance"><svg id="makerPlot" class="plot" viewBox="0 0 540 200" role="img" aria-label="Your six-point sparkline"></svg><div id="sliders" class="sliders"></div><div class="maker-controls"><button data-preset="rise">↗ A steady climb</button><button data-preset="spike">⌃ A big surprise</button><button data-preset="cycle">∿ A weekly rhythm</button></div><label class="toggles"><input id="zero" type="checkbox" checked>Start the vertical scale at zero</label><button class="primary" id="download">Save chart as SVG ↓</button><p id="saveStatus" role="status" class="footer-note"></p></div><aside class="note"><h3 id="makerTitle">Robot club attendance</h3><p id="makerStory" aria-live="polite"></p><div class="readout" id="stats"></div><p>Try turning the zero baseline off. The same six numbers can suddenly look much more dramatic.</p><p><strong>Detective’s rule:</strong> compare charts with the same time window, units, and scale. Then ask what the tiny picture leaves out.</p></aside></div></section>
<footer><span>Inspired by Jon’s <a href="?source=1">2005 note about sparklines</a>.<br>“The sparklines add a temporal dimension that is quite interesting.”</span><span>A little looking goes a long way.</span></footer></main>
<script>
'use strict';
const $=s=>document.querySelector(s);
const cases=[
{title:'The climbing club',q:'Three clubs all have 40 members today. Which one has been growing steadily, rather than recovering or fading?',unit:'Members · six months · shared scale 0–80',labels:['The Lantern Club','The Rocket Club','The Moss Club'],data:[[75,66,59,52,46,40],[10,16,22,28,34,40],[60,42,18,23,31,40]],answer:1,hint:'Cover the final dots. Which line keeps moving upward from the start?',why:'The Rocket Club rises at every point, from 10 to 40. The final number alone hides three very different journeys.',scale:[0,80]},
{title:'A perfectly peculiar Tuesday',q:'A toy shop usually sells about 10 robots a day. Which chart contains one unusually busy day, followed by a return to normal?',unit:'Robots sold · six days · shared scale 0–60',labels:['Window A','Window B','Window C'],data:[[8,10,9,52,10,9],[8,16,24,32,40,48],[12,10,8,10,12,10]],answer:0,hint:'You are looking for a mountain peak, not a staircase.',why:'Window A jumps to 52, then drops back to 10 and 9. That is a one-day spike, not sustained growth. The chart cannot tell us whether a sale, a birthday, or a robot invasion caused it.',scale:[0,60]},
{title:'The identical ending',q:'Each battery finishes at 50%. Which one stayed closest to 50% for the whole trip?',unit:'Battery charge (%) · six readings · shared scale 0–100',labels:['Scooter Finch','Scooter Wren','Scooter Robin'],data:[[10,95,15,90,20,50],[90,80,70,60,55,50],[49,51,50,48,52,50]],answer:2,hint:'A calm line has a small gap between its highest and lowest values.',why:'Scooter Robin stays between 48% and 52%. A sparkline can reveal stability that an end-of-trip reading completely misses.',scale:[0,100]},
{title:'The Saturday rhythm',q:'A miniature railway gets busier every other day in this little sample. Which line has the clearest repeating up-and-down rhythm?',unit:'Tickets · six days · shared scale 0–60',labels:['Platform One','Platform Two','Platform Three'],data:[[12,48,12,48,12,48],[10,18,26,34,42,50],[12,12,12,48,48,48]],answer:0,hint:'Try saying the values aloud: low, high, low, high…',why:'Platform One repeats 12, 48 three times. Repetition suggests a rhythm worth investigating, but six points are not enough to prove that it will continue forever.',scale:[0,60]},
{title:'The misleading magnifying glass',q:'These displays show the SAME six temperatures: 20, 21, 20, 22, 21, 22°C. Which panel makes the change look most dramatic?',unit:'Same data and time window · different vertical scales (read each card)',labels:['Scale 0–40°C','Scale 20–22°C','Scale 10–30°C'],data:[[20,21,20,22,21,22],[20,21,20,22,21,22],[20,21,20,22,21,22]],answer:1,hint:'A very narrow scale stretches a small change across the whole chart.',why:'Scale 20–22°C stretches a 2-degree change from bottom to top. The data are identical! A cropped scale can be useful for detail, but comparing its visual steepness to a zero-based chart would mislead.',scales:[[0,40],[20,22],[10,30]]},
{title:'Who travelled furthest?',q:'Two toy cars finish at the same position. Which travelled the greatest total distance along the track, including going backwards?',unit:'Position (metres) · six readings · shared scale 0–100',labels:['The Red Comet','The Mint Meteor','The Cream Cruiser'],data:[[0,20,40,60,80,100],[0,80,20,90,30,100],[0,0,0,0,0,100]],answer:1,hint:'Add every change in position as a positive distance, even when the line goes down.',why:'The Mint Meteor travels 340 metres: 80 + 60 + 70 + 60 + 70. The other cars travel 100 metres. A shared destination is not the same as a shared journey.',scale:[0,100]}
];
let current=0,closed=false,firstTry=0,attempts=0;
function chart(data,low,high,w=280,h=100){const pad=10,range=high-low||1;const pts=data.map((v,i)=>[pad+i*(w-2*pad)/(data.length-1),h-pad-(v-low)/range*(h-2*pad)]);return '<line x1="10" y1="'+(h-10)+'" x2="'+(w-10)+'" y2="'+(h-10)+'" stroke="#c8c7ad" stroke-dasharray="3 4"/><polyline points="'+pts.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#b43e2d" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>'+pts.map((p,i)=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="'+(i===data.length-1?5:3)+'" fill="'+(i===data.length-1?'#233e35':'#b43e2d')+'"/>').join('');}
function loadCase(){closed=false;attempts=0;const c=cases[current];$('#caseNo').textContent='Case '+String(current+1).padStart(2,'0')+' / 06';$('#stamp').textContent='OPEN CASE';$('#title').textContent=c.title;$('#question').textContent=c.q;$('#legend').textContent=c.unit;$('#feedback').hidden=true;$('#next').hidden=true;$('#hint').hidden=false;$('#progress').textContent='No clock. No pressure. Just clues.';$('#cards').innerHTML='';c.data.forEach((d,i)=>{const scale=c.scales?c.scales[i]:c.scale;const b=document.createElement('button');b.className='chart-card';b.setAttribute('aria-label',c.labels[i]+', values '+d.join(', '));b.innerHTML='<span class="card-label"><span class="letter">'+String.fromCharCode(65+i)+'</span>'+c.labels[i]+'</span><svg viewBox="0 0 280 100" aria-hidden="true">'+chart(d,...scale)+'</svg><span class="chart-caption"><span>start</span><span>now · '+d.at(-1)+'</span></span>';b.onclick=()=>answer(i,b);$('#cards').append(b);});}
function answer(i,b){if(closed)return;attempts++;const c=cases[current];$('#feedback').hidden=false;if(i!==c.answer){$('#feedback').textContent='Not quite. '+c.hint;$('#stamp').textContent='LOOK AGAIN';return;}closed=true;if(attempts===1)firstTry++;b.classList.add('selected');$('#feedback').textContent=c.why;$('#stamp').textContent='CASE CLOSED';$('#hint').hidden=true;$('#next').hidden=false;$('#next').textContent=current===5?'Close the casebook →':'Next case →';$('#progress').textContent=(current+1)+' of 6 mysteries solved';$('#cards').querySelectorAll('button').forEach(x=>{x.disabled=true;});}
$('#hint').onclick=()=>{$('#feedback').hidden=false;$('#feedback').textContent=cases[current].hint;};
$('#next').onclick=()=>{if(!closed)return;if(current<5){current++;loadCase();$('#title').setAttribute('tabindex','-1');$('#title').focus();}else{$('#caseBody').hidden=true;$('#end').hidden=false;$('#summary').textContent=firstTry+' of 6 spotted on your first look. Every solved case counts, including the ones you looked at twice.';$('#stamp').textContent='ALL FILED';}};
$('#restart').onclick=()=>{current=0;firstTry=0;$('#caseBody').hidden=false;$('#end').hidden=true;loadCase();};
function tab(maker){$('#make').hidden=!maker;$('#detect').hidden=maker;$('#makeTab').setAttribute('aria-pressed',String(maker));$('#detectTab').setAttribute('aria-pressed',String(!maker));}
$('#makeTab').onclick=()=>tab(true);$('#detectTab').onclick=()=>tab(false);$('#openMaker').onclick=()=>{tab(true);$('#chartName').focus();};
let values=[10,18,30,38,55,70];
values.forEach((v,i)=>{const label=document.createElement('label');label.innerHTML='Day '+(i+1)+'<input type="range" min="0" max="100" value="'+v+'" aria-label="Day '+(i+1)+' value"><output>'+v+'</output>';label.querySelector('input').oninput=e=>{values[i]=Number(e.target.value);label.querySelector('output').textContent=e.target.value;updateMaker();};$('#sliders').append(label);});
function updateMaker(){const min=Math.min(...values),max=Math.max(...values),mean=values.reduce((a,b)=>a+b,0)/6;const low=$('#zero').checked?0:min,high=Math.max(max,low+1);$('#makerPlot').innerHTML=chart(values,low,high,540,200);$('#makerPlot').setAttribute('aria-label',($('#chartName').value||'Untitled chart')+': '+values.join(', ')+'. Scale '+low+' to '+high);$('#makerTitle').textContent=$('#chartName').value||'Untitled tiny trend';const delta=values[5]-values[0];const path=values.slice(1).reduce((a,v,i)=>a+Math.abs(v-values[i]),0);let story=max===min?'A perfectly level little line. Every reading is the same.':path===Math.abs(delta)?'A steady journey '+(delta>0?'upward':'downward')+', with no reversals.':'A winding journey with at least one change of direction.';story+=' The last reading is '+Math.abs(delta)+' '+(delta>0?'above':delta<0?'below':'away from')+' the first.';$('#makerStory').textContent=story;$('#stats').textContent='LOW '+min+' / HIGH '+max+' / AVERAGE '+mean.toFixed(1)+' / SCALE '+low+'–'+high;$('#saveStatus').textContent='';}
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{values=({rise:[10,18,30,38,55,70],spike:[15,18,16,95,20,17],cycle:[15,75,15,75,15,75]})[b.dataset.preset].slice();$('#sliders').querySelectorAll('input').forEach((x,i)=>{x.value=values[i];x.nextElementSibling.textContent=values[i];});updateMaker();});
$('#zero').onchange=updateMaker;$('#chartName').oninput=updateMaker;
function escapeXML(s){return s.replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));}
$('#download').onclick=()=>{const low=$('#zero').checked?0:Math.min(...values),high=Math.max(...values,low+1);const svg='<svg xmlns="'+$('#makerPlot').namespaceURI+'" width="700" height="400" viewBox="0 0 700 400"><rect width="700" height="400" fill="#f9f5e6"/><text x="35" y="48" font-size="24" fill="#233e35" font-family="serif">'+escapeXML($('#chartName').value||'Untitled tiny trend')+'</text><g transform="translate(35,80)">'+chart(values,low,high,630,210)+'</g><text x="35" y="335" fill="#233e35" font-size="15" font-family="monospace">Values: '+values.join(' · ')+' | Scale: '+low+'–'+high+'</text><text x="35" y="373" fill="#57665a" font-size="13" font-family="serif">The Tiny Trend Detective / six moments, one little story</text></svg>';const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download='my-tiny-trend.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#saveStatus').textContent='Your SVG chart is ready. Open it in a browser or drop it into a document.';};
loadCase();updateMaker();
</script></body></html>
